#include <iostream>
using namespace std;

int main() {
    int n, s, sum = 0, maxValue = 0;
    cin >> n >> s;

    for (int i = 0; i < n; ++i) {
        int x;
        cin >> x;
        if (x > maxValue) maxValue = x;
        sum += x;
    }

    cout << (sum - maxValue <= s ? "NO" : "YES") << '\n';
    return 0;
}

